using System; using System.Collections.Generic; using System.Linq; using System.Text.Json; using System.Threading; using System.Threading.Tasks; using Parcs.Agent.Runtime;

public class BisectStep1 : IAgentComputation
{
    public class Out { public long count { get; set; } }
    public Task<AgentLayerResult> ExecuteAsync(AgentLayerInput input, CancellationToken ct)
    {
        const long M = 16777216L;
        int t = input.TotalWorkers, w = input.WorkerIndex;
        long chunk = (M + t - 1) / t;
        long s = w * chunk + 1, e = Math.Min(M, (w + 1) * chunk);
        double mid = 0.5; long c = 0;
        for (long i = s; i <= e; i++)
        {
            ulong z = (ulong)i * 0x9E3779B97F4A7C15UL;
            z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9UL;
            z = (z ^ (z >> 27)) * 0x94D049BB133111EBUL;
            z = z ^ (z >> 31);
            double v = (double)(z % 2147483647UL) / 2147483647.0;
            if (v <= mid) c++;
        }
        return Task.FromResult(AgentLayerResult.Ok(JsonSerializer.Serialize(new { count = c })));
    }
}

public class BisectStep2 : IAgentComputation
{
    public class In { public long count { get; set; } }
    public class Out { public double lo { get; set; } public double hi { get; set; } public double mid { get; set; } public long count { get; set; } }
    public Task<AgentLayerResult> ExecuteAsync(AgentLayerInput input, CancellationToken ct)
    {
        const long M = 16777216L; const long K = 5000000L;
        var prev = input.GetPreviousOutputs(0);
        long c1 = 0;
        foreach (var p in prev) if (p != null) c1 += JsonSerializer.Deserialize<In>(p).count;
        double lo = 0, hi = 1;
        double mid1 = (lo + hi) / 2;
        if (c1 >= K) hi = mid1; else lo = mid1;
        double mid = (lo + hi) / 2;
        int t = input.TotalWorkers, w = input.WorkerIndex;
        long chunk = (M + t - 1) / t;
        long s = w * chunk + 1, e = Math.Min(M, (w + 1) * chunk);
        long c = 0;
        for (long i = s; i <= e; i++)
        {
            ulong z = (ulong)i * 0x9E3779B97F4A7C15UL;
            z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9UL;
            z = (z ^ (z >> 27)) * 0x94D049BB133111EBUL;
            z = z ^ (z >> 31);
            double v = (double)(z % 2147483647UL) / 2147483647.0;
            if (v <= mid) c++;
        }
        return Task.FromResult(AgentLayerResult.Ok(JsonSerializer.Serialize(new Out { lo = lo, hi = hi, mid = mid, count = c })));
    }
}

public class BisectStep3 : IAgentComputation
{
    public class In { public double lo { get; set; } public double hi { get; set; } public double mid { get; set; } public long count { get; set; } }
    public Task<AgentLayerResult> ExecuteAsync(AgentLayerInput input, CancellationToken ct)
    {
        const long K = 5000000L;
        var prev = input.GetPreviousOutputs(0);
        long c2 = 0; double lo = 0, hi = 1, mid = 0;
        bool first = true;
        foreach (var p in prev)
        {
            if (p == null) continue;
            var d = JsonSerializer.Deserialize<In>(p);
            c2 += d.count;
            if (first) { lo = d.lo; hi = d.hi; mid = d.mid; first = false; }
        }
        if (c2 >= K) hi = mid; else lo = mid;
        double final = (lo + hi) / 2;
        return Task.FromResult(AgentLayerResult.Ok(JsonSerializer.Serialize(new { midpoint = final.ToString("R"), value = final, c2 = c2, mid2 = mid })));
    }
}

